CREATE OR REPLACE FUNCTION public.claim_initial_admin(_username text, _display_name text DEFAULT NULL::text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  current_user_id uuid := auth.uid();
  current_email text := lower(coalesce(auth.jwt() ->> 'email', ''));
  cleaned_username text := lower(trim(coalesce(_username, '')));
  final_display_name text := nullif(trim(coalesce(_display_name, '')), '');
BEGIN
  IF current_user_id IS NULL THEN
    RAISE EXCEPTION 'Faça login para concluir o cadastro inicial.';
  END IF;

  IF EXISTS (SELECT 1 FROM public.user_roles WHERE role = 'admin') THEN
    RAISE EXCEPTION 'O super administrador já foi criado. Cadastro bloqueado.';
  END IF;

  IF cleaned_username !~ '^[a-z0-9_.-]{3,40}$' THEN
    RAISE EXCEPTION 'Use um usuário de 3 a 40 caracteres com letras, números, ponto, hífen ou underline.';
  END IF;

  IF current_email = '' THEN
    RAISE EXCEPTION 'Não foi possível identificar o e-mail da conta.';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM public.profiles
    WHERE lower(username) = cleaned_username
      AND id <> current_user_id
  ) THEN
    RAISE EXCEPTION 'Este nome de usuário já está em uso.';
  END IF;

  INSERT INTO public.profiles (id, email, display_name, username)
  VALUES (
    current_user_id,
    current_email,
    coalesce(final_display_name, cleaned_username),
    cleaned_username
  )
  ON CONFLICT (id) DO UPDATE SET
    email = excluded.email,
    display_name = excluded.display_name,
    username = excluded.username,
    updated_at = now();

  INSERT INTO public.user_roles (user_id, role)
  VALUES (current_user_id, 'admin')
  ON CONFLICT (user_id, role) DO NOTHING;

  RETURN true;
END;
$function$

CREATE OR REPLACE FUNCTION public.receive_purchase_order_item(_item_id uuid, _quantity numeric, _location_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_item public.purchase_order_items%ROWTYPE;
  v_po public.purchase_orders%ROWTYPE;
  v_pending numeric;
  v_total_qty numeric;
  v_total_recv numeric;
BEGIN
  IF NOT public.is_staff(auth.uid()) THEN
    RAISE EXCEPTION 'Sem permissão.';
  END IF;
  IF _quantity <= 0 THEN
    RAISE EXCEPTION 'Quantidade deve ser positiva.';
  END IF;

  SELECT * INTO v_item FROM public.purchase_order_items WHERE id = _item_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Item não encontrado.'; END IF;

  SELECT * INTO v_po FROM public.purchase_orders WHERE id = v_item.purchase_order_id FOR UPDATE;
  IF v_po.status = 'canceled' THEN RAISE EXCEPTION 'Pedido cancelado.'; END IF;

  v_pending := v_item.quantity - v_item.received_quantity;
  IF _quantity > v_pending THEN
    RAISE EXCEPTION 'Quantidade acima do pendente (%.).', v_pending;
  END IF;

  -- stock entry
  INSERT INTO public.stock_movements (product_id, location_id, kind, quantity, reason, document, unit_cost, created_by)
  VALUES (
    v_item.product_id,
    COALESCE(_location_id, v_po.location_id),
    'in',
    _quantity,
    'Recebimento OC ' || v_po.code,
    v_po.code,
    v_item.unit_cost,
    auth.uid()
  );

  -- update item
  UPDATE public.purchase_order_items
    SET received_quantity = received_quantity + _quantity
    WHERE id = _item_id;

  -- supplier cost history
  INSERT INTO public.supplier_product_costs (supplier_id, product_id, unit_cost, purchase_order_id)
  VALUES (v_po.supplier_id, v_item.product_id, v_item.unit_cost, v_po.id);

  -- refresh PO status
  SELECT COALESCE(SUM(quantity),0), COALESCE(SUM(received_quantity),0)
    INTO v_total_qty, v_total_recv
    FROM public.purchase_order_items WHERE purchase_order_id = v_po.id;

  UPDATE public.purchase_orders
    SET status = CASE
      WHEN v_total_recv >= v_total_qty THEN 'received'::purchase_order_status
      WHEN v_total_recv > 0 THEN 'partial'::purchase_order_status
      ELSE status
    END,
    received_at = CASE WHEN v_total_recv >= v_total_qty THEN now() ELSE received_at END
    WHERE id = v_po.id;
END;
$function$

CREATE OR REPLACE FUNCTION public.resolve_login_email(_identifier text)
 RETURNS text
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  cleaned text := lower(trim(coalesce(_identifier, '')));
  resolved_email text;
BEGIN
  IF cleaned = '' OR length(cleaned) > 200 THEN
    RAISE EXCEPTION 'Usuário ou senha inválidos.';
  END IF;

  IF position('@' in cleaned) > 0 THEN
    RETURN cleaned;
  END IF;

  SELECT lower(email)
    INTO resolved_email
  FROM public.profiles
  WHERE lower(username) = cleaned
  LIMIT 1;

  IF resolved_email IS NULL THEN
    RAISE EXCEPTION 'Usuário ou senha inválidos.';
  END IF;

  RETURN resolved_email;
END;
$function$
